{
  "requirements": [
    {
      "id": "F-01",
      "text": "The system shall ensure secure authentication and encryption of user data to protect sensitive attendance information.",
      "quality_axes": ["Safety", "Trustworthiness"],
      "derived_from": ["SAF-01", "TRU-01"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-02",
      "text": "The system shall provide real-time data synchronization and processing within 2 seconds to maintain accuracy and efficiency in attendance tracking.",
      "quality_axes": ["Safety", "Efficiency"],
      "derived_from": ["SAF-02", "EFF-01"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-03",
      "text": "The system shall implement automated alerts for discrepancies in attendance reporting to ensure data accuracy.",
      "quality_axes": ["Safety"],
      "derived_from": ["SAF-03"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-04",
      "text": "The system shall store historical attendance data for a minimum of five academic years to support compliance and analysis.",
      "quality_axes": ["Safety", "Responsibility"],
      "derived_from": ["SAF-04", "RES-07"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-05",
      "text": "The system shall generate attendance reports within 5 seconds for up to 1000 students while ensuring data protection compliance.",
      "quality_axes": ["Efficiency", "Responsibility"],
      "derived_from": ["EFF-03", "RES-01"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-06",
      "text": "The system shall allow students to view their attendance records with a response time of under 3 seconds after successful authentication.",
      "quality_axes": ["Efficiency", "Trustworthiness"],
      "derived_from": ["EFF-05", "TRU-04"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-07",
      "text": "The system shall implement role-based access control to restrict data access based on user roles while allowing dispute processes.",
      "quality_axes": ["Trustworthiness", "Responsibility"],
      "derived_from": ["TRU-02", "RES-03"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-08",
      "text": "The system shall integrate energy-efficient algorithms in attendance processing to minimize energy consumption without compromising performance.",
      "quality_axes": ["Sustainability", "Efficiency"],
      "derived_from": ["GRN-01", "EFF-01"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-09",
      "text": "The system shall provide logging for all attendance modifications to support accountability and traceability.",
      "quality_axes": ["Safety", "Trustworthiness"],
      "derived_from": ["SAF-05"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-10",
      "text": "The system shall allow for manual overrides by authorized personnel in cases of system failure or error.",
      "quality_axes": ["Safety"],
      "derived_from": ["SAF-06"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-11",
      "text": "The system shall maintain an audit log of all access and modifications to attendance records.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-03"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-12",
      "text": "The system shall undergo regular security audits to identify and mitigate potential vulnerabilities.",
      "quality_axes": ["Safety"],
      "derived_from": ["SAF-07"],
      "kaos_level": "operational",
      "parent": null
    }
  ],
